    "id": "gastosdeventageneralesyadministrativosai",
    "num": 198,
    "disp": "Gastos de Venta, Generales y Administrativos a Ingresos (SG&A a Ingresos)",
    "cat": "ratios",
    "cats": "Ratios y valuación",
